    "lastingImpact": "Formed the intellectual bedrock of republicanism, constitutional democracy, and political theory.",
    "audioSpeechText": "Men of Achaean League! Look upon our temples and the graves of your fathers! We fight not for a king's vanity, but for the liberty of free citizens. Hold the line, and let Hellas remember our courage for all time!"
